memory.event_counter_source:
// Local evidence tool: streaming accounting for Heaptrack 1.5 raw format 3.
// It does not symbolize or intern (size, trace) pairs; retained state is bounded
// by trace definitions and currently live allocations, not allocation history.
#include <algorithm>
#include <array>
#include <charconv>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>

using U = std::uint64_t;
struct Trace { U ip, parent, calls = 0, bytes = 0, temporary = 0; };
struct Allocation { U size, trace; };

U number(const std::string& line, std::size_t& cursor) {
    while (cursor < line.size() && line[cursor] == ' ') ++cursor;
    U value = 0;
    const auto result = std::from_chars(line.data() + cursor,
                                        line.data() + line.size(), value, 16);
    if (result.ec != std::errc{}) throw std::runtime_error("invalid hex field");
    cursor = result.ptr - line.data();
    return value;
}
void add(U& total, U value) {
    if (value > std::numeric_limits<U>::max() - total)
        throw std::runtime_error("counter overflow");
    total += value;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::vector<Trace> traces(1);
    std::unordered_map<U, Allocation> live;
    live.reserve(16384);
    std::vector<std::string> modules;
    std::array<U, 256> modes{};
    U allocations = 0, frees = 0, unknown_frees = 0, temporary = 0;
    U traffic = 0, heap = 0, peak = 0, peak_blocks = 0, last = 0;
    U page_size = 0, peak_rss_pages = 0, duration_ms = 0, lines = 0;
    bool version = false;
    std::string line;
    try {
        while (std::getline(std::cin, line)) {
            ++lines;
            if (line.empty()) throw std::runtime_error("empty record");
            const auto mode = static_cast<unsigned char>(line[0]);
            ++modes[mode];
            std::size_t cursor = 1;
            switch (mode) {
            case 'v':
                (void)number(line, cursor);
                if (number(line, cursor) != 3 || version || lines != 1)
                    throw std::runtime_error("expected one format-3 header");
                version = true;
                break;
            case 't': {
                const U ip = number(line, cursor), parent = number(line, cursor);
                if (!version || parent >= traces.size())
                    throw std::runtime_error("invalid trace parent");
                traces.push_back({ip, parent});
                break;
            }
            case '+': {
                const U size = number(line, cursor), trace = number(line, cursor);
                const U pointer = number(line, cursor);
                if (!version || trace == 0 || trace >= traces.size() || pointer == 0)
                    throw std::runtime_error("invalid allocation");
                if (!live.emplace(pointer, Allocation{size, trace}).second)
                    throw std::runtime_error("duplicate live pointer");
                add(allocations, 1);
                add(traffic, size);
                add(heap, size);
                peak = std::max(peak, heap);
                peak_blocks = std::max(peak_blocks, static_cast<U>(live.size()));
                add(traces[trace].calls, 1);
                add(traces[trace].bytes, size);
                last = pointer;
                break;
            }
            case '-': {
                const U pointer = number(line, cursor);
                const bool is_temporary = last == pointer;
                last = 0;
                const auto found = live.find(pointer);
                if (found == live.end()) {
                    add(unknown_frees, 1);
                    break;
                }
                if (is_temporary) {
                    add(temporary, 1);
                    add(traces[found->second.trace].temporary, 1);
                }
                if (found->second.size > heap)
                    throw std::runtime_error("heap underflow");
                heap -= found->second.size;
                live.erase(found);
                add(frees, 1);
                break;
            }
            case 'I':
                page_size = number(line, cursor);
                (void)number(line, cursor);
                break;
            case 'R':
                peak_rss_pages = std::max(peak_rss_pages, number(line, cursor));
                break;
            case 'c':
                duration_ms = std::max(duration_ms, number(line, cursor));
                break;
            case 'm':
                modules.push_back(line);
                break;
            case 'x': case 'X': case '#':
                break;
            default:
                throw std::runtime_error("unsupported raw record mode");
            }
        }
        if (!std::cin.eof() || !version)
            throw std::runtime_error("incomplete input read");
        U live_sum = 0;
        for (const auto& [pointer, allocation] : live) add(live_sum, allocation.size);
        if (live_sum != heap || allocations - frees != live.size())
            throw std::runtime_error("final live-state invariant failed");
        std::vector<std::size_t> order;
        for (std::size_t i = 1; i < traces.size(); ++i)
            if (traces[i].calls) order.push_back(i);
        std::sort(order.begin(), order.end(), [&](auto a, auto b) {
            if (traces[a].calls != traces[b].calls) return traces[a].calls > traces[b].calls;
            return a < b;
        });
        std::cout << "{\n\"format\":3,\"records\":" << lines
                  << ",\"allocations\":" << allocations << ",\"frees\":" << frees
                  << ",\"untracked_frees\":" << unknown_frees
                  << ",\"temporary_allocations\":" << temporary
                  << ",\"allocated_bytes\":" << traffic
                  << ",\"peak_live_bytes\":" << peak
                  << ",\"end_live_bytes\":" << heap
                  << ",\"peak_live_allocations\":" << peak_blocks
                  << ",\"end_live_allocations\":" << live.size()
                  << ",\"trace_count\":" << traces.size() - 1
                  << ",\"duration_ms\":" << duration_ms
                  << ",\"page_size\":" << page_size
                  << ",\"recorded_peak_rss_pages\":" << peak_rss_pages
                  << ",\n\"record_counts\":{";
        bool comma = false;
        for (std::size_t i = 0; i < modes.size(); ++i) if (modes[i]) {
            if (comma) std::cout << ',';
            comma = true;
            std::cout << std::quoted(std::string(1, static_cast<char>(i))) << ':' << modes[i];
        }
        std::cout << "},\n\"module_records\":[";
        for (std::size_t i = 0; i < modules.size(); ++i) {
            if (i) std::cout << ',';
            std::cout << std::quoted(modules[i]);
        }
        std::cout << "],\n\"top_allocation_traces\":[";
        order.resize(std::min<std::size_t>(32, order.size()));
        for (std::size_t rank = 0; rank < order.size(); ++rank) {
            if (rank) std::cout << ',';
            auto index = order[rank];
            const auto& trace = traces[index];
            std::cout << "\n{\"trace\":" << index << ",\"allocations\":" << trace.calls
                      << ",\"bytes\":" << trace.bytes << ",\"temporary\":" << trace.temporary
                      << ",\"ips\":[";
            bool separated = false;
            while (index) {
                if (separated) std::cout << ',';
                separated = true;
                std::cout << '"' << std::hex << traces[index].ip << std::dec << '"';
                index = traces[index].parent;
            }
            std::cout << "]}";
        }
        std::cout << "]\n}\n";
    } catch (const std::exception& error) {
        std::cerr << "Raw accounting rejected input at line " << lines
                  << ": " << error.what() << '\n';
        return 1;
    }
}
